// Teaching models. Rates in forms are percentages; money uses the form's unit.
const n=(x,d=2)=>Number(x).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const pct=x=>n(100*x)+'%';
const f=(label,key,value,min,max,unit='')=>[label,key,value,min,max,1,unit];
const annuity=(cash,rate,years)=>Array.from({length:years},(_,i)=>cash/(1+rate)**(i+1)).reduce((a,b)=>a+b,0);
export const topicLabs={
 bank:{title:'银行货币创造与资本约束',description:'比较简化准备金约束与资本约束，理解为什么放贷能力不会无限增长。',fields:[f('新增基础准备金','reserve',100,0,1e9,'万元'),f('假设准备金率','rr',10,.1,100,'%'),f('可用监管资本','capital',80,0,1e9,'万元'),f('假设资本比率要求','car',10,.1,100,'%'),f('简化风险权重','rw',100,.1,300,'%')],run:d=>{const deposits=d.reserve/(d.rr/100),assets=d.capital/(d.car/100)/(d.rw/100);return {stats:[['简化存款扩张上限',n(deposits)+' 万元'],['简化贷款扩张',n(deposits-d.reserve)+' 万元'],['资本口径支持的资产',n(assets)+' 万元']],note:'封闭、无现金漏损、无超额准备金且资金连续再存入的教材模型；资本比率和风险权重均为假设，不是实际监管门槛。两类指标口径不同，不能机械相加；真实放贷还受需求、信用风险、流动性和盈利约束。'};}},
 markets:{title:'一级融资与股权稀释',description:'新股融资增加公司资金，也改变原股东持股比例。',fields:[f('原有股份','shares',1000,1,1e10,'万股'),f('新发行股份','newShares',250,0,1e10,'万股'),f('发行价格','price',10,.01,1e6,'元'),f('发行费用比例','fee',3,0,100,'%')],run:d=>({stats:[['募集净额',n(d.newShares*d.price*(1-d.fee/100))+' 万元'],['原股东发行后占比',pct(d.shares/(d.shares+d.newShares))],['新增股份占比',pct(d.newShares/(d.shares+d.newShares))]],note:'同权普通股一次发行，单位万股×元=万元；未计税费以外的调整、期权及其他潜在稀释。持股比例下降不必然等于经济价值损失；二级市场普通交易通常不向发行人提供新增资金。'})},
 macro:{title:'GDP支出法与实际增长',description:'把总需求分项相加，再区分名义变化与价格变化。',fields:[f('消费 C','consumption',600,0,1e9,'亿元'),f('投资 I','investment',200,0,1e9,'亿元'),f('政府购买 G','government',200,0,1e9,'亿元'),f('出口 X','exports',100,0,1e9,'亿元'),f('进口 M','imports',80,0,1e9,'亿元'),f('上期名义GDP','previous',950,.01,1e9,'亿元'),f('GDP平减指数涨幅','inflation',3,-90,100,'%')],run:d=>{const gdp=d.consumption+d.investment+d.government+d.exports-d.imports;if(gdp<=0)throw Error('本模型的GDP需大于零，请检查分项。');return {stats:[['名义GDP',n(gdp)+' 亿元'],['名义增长率',pct(gdp/d.previous-1)],['实际增长率近似口径',pct(gdp/d.previous/(1+d.inflation/100)-1)]],note:'GDP=C+I+G+X−M；政府转移支付不能直接作为政府购买重复计入。实际增长使用两期间GDP平减指数比率，不直接用CPI替代；各分项须按国民核算口径一致计量。'};}},
 policy:{title:'利率政策与实际利率',description:'试验名义利率、预期通胀与简化政策规则之间的联系。',fields:[f('名义利率','nominal',5,-20,100,'%'),f('预期通胀率','expectedInflation',3,-50,100,'%'),f('当前通胀率假设','inflation',3,-50,100,'%'),f('中性实际利率假设','neutral',1,-10,20,'%'),f('通胀目标假设','target',2,-10,20,'%'),f('产出缺口假设','gap',0,-30,30,'%')],run:d=>({stats:[['事前实际利率',pct((1+d.nominal/100)/(1+d.expectedInflation/100)-1)],['简化泰勒规则名义利率',n(d.neutral+d.inflation+.5*(d.inflation-d.target)+.5*d.gap)+'%']],note:'规则系数均设为0.5，仅为教学演示，不代表任何央行的实际反应函数或利率预测。中性利率、预期通胀和产出缺口存在估计误差；政策传导还受银行、信用和预期影响。'})},
 fiscal:{title:'财政乘数与债务动态',description:'分别观察简化支出乘数与债务占GDP的变化。',fields:[f('新增政府购买','spending',100,0,1e9,'亿元'),f('边际消费倾向','mpc',.8,0,.99),f('上期债务/GDP','debtRatio',60,0,500,'%'),f('债务平均名义利率','interest',4,-10,100,'%'),f('名义GDP增长率','growth',3,-90,100,'%'),f('初级财政赤字/GDP','primary',1,-50,50,'%')],run:d=>({stats:[['简单凯恩斯乘数',n(1/(1-d.mpc))+' 倍'],['教材模型产出增量',n(d.spending/(1-d.mpc))+' 亿元'],['简化下一期债务/GDP',n((1+d.interest/100)/(1+d.growth/100)*d.debtRatio+d.primary)+'%']],note:'乘数假设封闭经济、价格固定、无税收及进口漏损、无挤出效应且存在闲置产能；不应当作真实财政效果预测。债务动态另按初级赤字占当期GDP，忽略估值及其他存量流量调整，两种模型不直接联立。'})},
 global:{title:'海外投资与本币回报',description:'资产涨了，换回本币后仍可能亏损。',fields:[f('本币投入','principal',100000,1,1e12,'元'),f('海外资产外币收益','assetReturn',8,-100,1000,'%'),f('买入汇率（本币/外币）','initialFx',9,.0001,1e5),f('期末汇率（本币/外币）','endFx',8.5,.0001,1e5)],run:d=>{const total=(1+d.assetReturn/100)*d.endFx/d.initialFx-1;return {stats:[['本币总回报率',pct(total)],['换回后的本币金额',n(d.principal*(1+total))+' 元'],['外币相对本币变化',pct(d.endFx/d.initialFx-1)]],note:'本币回报=(1+外币资产回报)×期末汇率/期初汇率−1。汇率采用本币/外币报价，未计费用、税收及对冲；同一币种不同资产也有各自风险。'};}},
 option:{title:'看涨与看跌期权损益',description:'区分到期支付、权利金和最终损益。',fields:[f('到期标的价格 S','spot',110,0,1e8,'元'),f('行权价 K','strike',100,.01,1e8,'元'),f('每单位期权费','premium',8,0,1e8,'元'),f('标的单位数量','quantity',100,1,1e8,'单位')],run:d=>({stats:[['买入看涨期权到期损益',n((Math.max(d.spot-d.strike,0)-d.premium)*d.quantity)+' 元'],['买入看跌期权到期损益',n((Math.max(d.strike-d.spot,0)-d.premium)*d.quantity)+' 元'],['看涨到期盈亏平衡标的价',n(d.strike+d.premium)+' 元'],['看跌到期盈亏平衡标的价',d.premium>d.strike?'非负标的价格下无法盈亏平衡':n(d.strike-d.premium)+' 元']],note:'仅欧式买方到期损益，忽略利息和交易费用。权利金在初始支付，到期价值不等于利润；中途市场价值还受剩余时间、波动率与利率等因素影响。数量为对应标的单位，不能忽略合约乘数。'})},
 risk:{title:'正态VaR与预期损失',description:'看见常规波动与尾部风险的区别。',fields:[f('组合价值','value',1000000,1,1e12,'元'),f('年波动率','vol',20,0,300,'%'),f('持有期','days',10,1,252,'交易日'),f('违约概率 PD','pd',2,0,100,'%'),f('违约损失率 LGD','lgd',60,0,100,'%')],run:d=>({stats:[['99%正态VaR（零均值）',n(2.326347874*d.value*d.vol/100*Math.sqrt(d.days/252))+' 元'],['对应一年信用预期损失',n(d.value*d.pd/100*d.lgd/100)+' 元']],note:'VaR使用独立同分布、正态收益、252交易日及零均值近似，不是最大可能亏损，也未刻画跳跃与流动性。信用预期损失=EAD×PD×LGD，另以组合价值作EAD、PD作一年期假设；两项时间口径不同，不能直接相加。'})},
 behavior:{title:'回撤与回本难度',description:'亏损和上涨的分母不同，回本需要的涨幅并不对称。',fields:[f('投入本金','principal',100000,1,1e12,'元'),f('已发生回撤','drawdown',30,0,100,'%')],run:d=>({stats:[['回撤后金额',n(d.principal*(1-d.drawdown/100))+' 元'],['回到原本金所需涨幅',d.drawdown===100?'本金归零，无法仅靠该余额增长回本':pct(1/(1-d.drawdown/100)-1)]],note:'仅展示比例与参考点效应，不预测未来回报；沉没成本不会改变资产此后的风险和现金流。是否持有应重新看当前价值与目标，不能只因想回本而加仓。'})},
 corporate:{title:'资本成本与项目净现值',description:'统一税后经营现金流与资金成本口径。',fields:[f('初始项目投入','initial',1000,0,1e12,'万元'),f('每年年末自由现金流','cashflow',300,-1e10,1e10,'万元'),f('持续年数','years',5,1,50,'年'),f('股权资金比例','equityWeight',60,0,100,'%'),f('股权成本','equityCost',12,0,100,'%'),f('债务成本','debtCost',6,0,100,'%'),f('所得税率','tax',25,0,100,'%')],run:d=>{if(!Number.isInteger(d.years))throw Error('请填写整数年限。');const w=d.equityWeight/100,r=w*d.equityCost/100+(1-w)*d.debtCost/100*(1-d.tax/100);return {stats:[['简化加权资本成本 WACC',pct(r)],['项目净现值 NPV',n(annuity(d.cashflow,r,d.years)-d.initial)+' 万元']],note:'资本结构权重应以目标市场价值口径衡量，假设利息税盾可实现；未来现金流为税后FCFF，固定年末发生、无终值及融资现金流。NPV为正只说明给定假设下覆盖了要求回报。'};}},
 pricing:{title:'CAPM与风险溢价',description:'把无风险基准与承担的市场风险分开。',fields:[f('无风险利率','rf',3,-10,30,'%'),f('市场预期收益率','market',8,-50,100,'%'),f('资产Beta','beta',1.2,-5,5),f('资产假设预期收益','expected',10,-100,200,'%')],run:d=>{const required=d.rf+d.beta*(d.market-d.rf);return {stats:[['CAPM要求回报率',n(required)+'%'],['假设预期收益减要求回报',n(d.expected-required)+' 个百分点']],note:'CAPM=Rf+Beta×(E[Rm]−Rf)。Beta刻画模型中的系统性风险，不等于总波动或最大损失；输入是估计，差额也不是可保证的超额收益。币种、期限与收益口径需一致。'};}},
 quant:{title:'回测成本与夏普比率',description:'把漂亮的毛回报还原成扣成本后的模型结果。',fields:[f('毛年收益率','gross',12,-100,200,'%'),f('每年交易额/平均资产','turnover',10,0,1000,'倍'),f('每笔成交额费率','costBps',5,0,500,'基点'),f('年波动率','vol',15,0,300,'%'),f('无风险利率','rf',3,-20,30,'%')],run:d=>{const drag=d.turnover*d.costBps/10000,net=d.gross/100-drag;return {stats:[['简化成本拖累',pct(drag)],['扣线性成本后年收益',pct(net)],['简化夏普比率',d.vol>0?n((net-d.rf/100)/(d.vol/100),3):'波动率为零，不适用']],note:'交易额按买卖实际成交额合计，避免单边与双边重复；成本拖累为线性近似，未计市场冲击、融资、复利和税收。回测还应防范前视、幸存者和过拟合偏差，使用样本外验证。'};}},
 fund:{title:'管理费与业绩报酬',description:'先看收费基数和顺序，再看投资者净回报。',fields:[f('期初基金净资产','initial',10000,.01,1e12,'万元'),f('投资毛回报率','gross',12,-100,1000,'%'),f('管理费率','management',2,0,10,'%'),f('业绩报酬比例','performance',20,0,100,'%'),f('简化门槛收益率','hurdle',5,0,100,'%')],run:d=>{const management=d.initial*d.management/100,pre=Math.max(0,d.initial*(1+d.gross/100)-management),perf=Math.max(0,pre-d.initial*(1+d.hurdle/100))*d.performance/100,net=pre-perf;return {stats:[['管理费',n(management)+' 万元'],['业绩报酬',n(perf)+' 万元'],['投资者期末净资产',n(net)+' 万元'],['投资者净回报',pct(net/d.initial-1)]],note:'管理费按期初资产收取，随后仅对超过硬门槛的扣管理费后收益计提业绩报酬。未模拟高水位线、追赶、现金流和其他费用；净资产最低按零展示，资产不足以支付全部费用时未进一步模拟费用债权或清盘。真实合同条款可能不同，不直接套用本模型。'};}},
 regulation:{title:'资本与流动性比率',description:'资本缓冲和短期现金缓冲解决不同问题。',fields:[f('符合口径的监管资本','capital',100,0,1e9,'亿元'),f('风险加权资产 RWA','rwa',800,.01,1e10,'亿元'),f('合格优质流动性资产','hqla',120,0,1e9,'亿元'),f('压力下30日净现金流出','outflow',100,.01,1e9,'亿元')],run:d=>({stats:[['资本比率',pct(d.capital/d.rwa)],['简化流动性覆盖率 LCR',pct(d.hqla/d.outflow)]],note:'分子分母需满足适用规则的资格、折扣与限额。此处只演示比率结构，不作监管达标判断；实际要求取决于机构、地区、缓冲、过渡安排与具体风险。'})}
};
export function runTopicLab(kind,data){const lab=topicLabs[kind];if(!lab)throw Error('未知实验。');for(const [,key,,min,max] of lab.fields){if(!Number.isFinite(data[key])||data[key]<min||data[key]>max)throw Error('请填写范围内的有效数字。');}return lab.run(data);}
